  try{for(Paragraph para:ps){paint.setTypeface(para.level<2?Typeface.create("sans-serif",Typeface.BOLD):Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(para.level==0?23:para.level==1?15:11);
    StaticLayout layout=StaticLayout.Builder.obtain(para.text,0,para.text.length(),paint,493).setIncludePad(false).setLineSpacing(4,1).build();
    if(page==null){page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNo).create());canvas=page.getCanvas();y=48;}
    if(para.level<2&&y+Math.min(layout.getHeight()+35,100)>783){footer(canvas,pageNo);doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNo).create());canvas=page.getCanvas();y=48;}
    for(int line=0;line<layout.getLineCount();line++){float h=layout.getLineBottom(line)-layout.getLineTop(line);if(y+h>783){footer(canvas,pageNo);doc.finishPage(page);page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,++pageNo).create());canvas=page.getCanvas();y=48;}
     String text=para.text.substring(layout.getLineStart(line),layout.getLineEnd(line)).replace("\n","");canvas.drawText(text,51,y+(layout.getLineBaseline(line)-layout.getLineTop(line)),paint);y+=h;}
    y+=para.level==0?18:para.level==1?10:9;
   }if(page!=null){footer(canvas,pageNo);doc.finishPage(page);}try(OutputStream out=new FileOutputStream(f)){doc.writeTo(out);}
  }finally{doc.close();}
